    return json.dumps(value, ensure_ascii=False)


def plan(members: dict, aliases: dict, settings: dict, keep_rows: list, now_stamp: str):
    """(groups, refused): groups are dicts with the survivor, merged, rules, changes, sources."""
    info = {}
    for n, rec in members.items():
        key = name_key(rec["name"])
        info[n] = {
            "name": key,
            "given": key.split(" ")[0] if key else "",
            "email": email_key(rec["email"], settings),
            "phone": phone_key(rec["phone"], settings),
            "dob": dates.parse_day(rec["dob"]),
            "at": parse_updated(rec["updated"]),
        }
