        if ga == gb:
            continue
        if any(kept_apart(x, y) for x in sets[ga] for y in sets[gb]):
            refused.append((a, b, RULES[rule]))
            continue
        sets[ga] |= sets[gb]
        rules[ga] |= rules[gb] | {rule}
        for n in sets[gb]:
            group_of[n] = ga
        del sets[gb], rules[gb]

    groups = []
    for root, group in sets.items():
        if len(group) < 2:
            continue
        groups.append(_merge_group(members, info, group, rules[root], now_stamp))
    groups.sort(key=lambda g: g["survivor"])
    return groups, refused


def _merge_group(members, info, group, rule_set, now_stamp):
    survivor = min(group, key=lambda n: (dates.parse_day(members[n]["joined"]), n))
    order = sorted(group, key=lambda n: (-info[n]["at"].timestamp(), n))
    old = members[survivor]
    new = dict(old)
    sources = {}

    def first(field):
        for n in order:
            if members[n][field] != "":
                return members[n][field], n
        return "", None

    new["name"], source = (old["name"], survivor) if old["name"] != "" else first("name")
    sources["name"] = source
    for field in ("email", "phone", "dob"):
        new[field], sources[field] = first(field)
    days = [(dates.parse_day(members[n]["expires"]), n) for n in order if members[n]["expires"] != ""]
    if days:
        latest = max(day for day, _ in days)
        source = next(n for day, n in days if day == latest)
        new["expires"], sources["expires"] = members[source]["expires"], source
    else:
        new["expires"], sources["expires"] = "", None
    marks = {members[n]["marketing"] for n in group}
    new["marketing"] = "no" if "no" in marks else "yes" if "yes" in marks else ""
    new["tags"] = sorted({tag for n in group for tag in tag_list(members[n])})
    new["updated"] = now_stamp

    changes, origin = {}, {}
    for field in ("name", "email", "phone", "dob", "expires", "marketing", "tags", "updated"):
        if new[field] != old[field]:
            changes[field] = [old[field], new[field]]
            if field in sources:
                origin[field] = ids.fmt(sources[field])
    merged = sorted(group - {survivor})
    return {
        "survivor": survivor,
        "merged": merged,
        "rules": [RULES[r] for r in sorted(rule_set)],
        "record": new,
        "changes": changes,
        "from": origin,
    }


def render(groups, refused, applied: bool) -> list[str]:
    lines = []
    for g in groups:
        merged = ", ".join(ids.fmt(n) for n in g["merged"])
        lines.append(f"merge {ids.fmt(g['survivor'])} <- {merged} ({', '.join(g['rules'])})")
        for field, (before, after) in g["changes"].items():
            lines.append(f"  {field}: {_dumps(before)} -> {_dumps(after)}")
    for a, b, rule in refused:
        lines.append(f"kept apart {ids.fmt(a)} {ids.fmt(b)} ({rule})")
    count = sum(len(g["merged"]) for g in groups)
    lines.append(f"{len(groups)} groups, {count} members merged, {len(refused)} pairs kept apart")
    if not applied:
        lines.append("dry run: nothing written")
    return lines


def entries(ctx, groups) -> list[dict]:
    out = []
    seq = audit.next_seq(ctx.entries)
    for g in groups:
        out.append({
            "seq": seq, "at": ctx.stamp, "op": "merge", "by": ctx.by, "member": ids.fmt(g["survivor"]),
            "merged": [ids.fmt(n) for n in g["merged"]], "rules": g["rules"],
            "changes": g["changes"], "from": g["from"],
        })
        seq += 1
    return out
